We study the problem of solving the system of nonlinear equations
\begin{align}
\label{eq:ori_prob}
    \vf(\vx) = \vzero,
\end{align}
where the nonlinear vector function $\vf:\BR^d\to\BR^n$ is Lipschitz continuous and its Jacobian is H\"older continuous.


We let $[n]=\{1,\dots,n\}$ and use the notation $t\%n$ to present the remainder of $t$ divided by $n$.
We denote $\ve_i\in\BR^n$ as the $i$-th standard basis vector of the $n$-dimensional Euclidean space for all $i\in [n]$. 
We use $\Norm{\cdot}$ to represent the Euclidean norm for a given vector and the spectral norm for a given matrix. 
Moreover, we use the notation $\sigma_{\min}(\cdot)$ to represent the smallest singular value for a given matrix.

For the system of nonlinear equations (\ref{eq:ori_prob}), we partition the vector function $\vf:\BR^d\to\BR^n$ at $\vx\in\BR^d$ as~$\vf(\vx)=[f_1(\vx),\dots, f_n(\vx)]^\top\in\BR^n$, where $f_i:\BR^d\to\BR$.
We also denote the gradient of component $f_i(\cdot)$ at $\vx\in\BR^d$ as $\vg_i(\vx)=\nabla f_i(\vx)$, and we organize the corresponding Jacobian as~$\mJ(\vx)=[\vg_1(\vx), \cdots, \vg_n(\vx)]^\top\in\BR^{n\times d}$.


\begin{asm}
\label{asm:L-f}
    We suppose the vector function $\vf:\BR^d\to\BR^n$ is Lipschitz continuous, i.e., there exists constant $L_f>0$ such that
    \begin{align}
        \Norm{\vf(\vx)-\vf(\vy)} \leq L_f\Norm{\vx - \vy}
    \end{align}
    for all $\vx,\vy\in\BR^d$.
\end{asm}

\begin{asm}\label{asm:holder-g}
    We suppose the Jacobian $\mJ:\BR^d\to\BR^{n\times d}$  is $\nu$-H\"older continuous for some $\nu\in(0,1]$, i.e., there exists constant $\fH_\nu>0$ such that
    \begin{align}
        \Norm{\mJ(\vx)-\mJ(\vy)} \leq \fH_\nu\Norm{\vx - \vy}^\nu
    \end{align}
    for all $\vx,\vy\in\BR^d$.
\end{asm}

\begin{asm}
\label{asm:b-J-sing}
    The system of the nonlinear equations (\ref{eq:ori_prob}) holds $n\geq d$ and has a non-degenerate solution $\vx^*\in\BR^d$, i.e., there exists some $\mu>0$ such that
    \begin{align}
    \label{eq:b-J-sing}
    \mu = \sigma_{\min} (\mJ(\vx^*))> 0.
    \end{align}
\end{asm}

\begin{algorithm}[t]
\caption{Incremental Gauss–Newton Method (\texttt{IGN})}
\label{alg:IGN-1}
\begin{algorithmic}[1]
\State \textbf{Input:} $\vx^0\in\BR^d$, $\vu^0\in\BR^d$, $\mH^0,\mG^0\in\BR^{d\times d}$  \vskip0.1cm
\State \textbf{for} $t=0,1,\dots$ \vskip0.12cm
\State \quad  $\vx^{t+1}=\mG^t\vu^t$ \vskip0.12cm
\State \quad  $i_t =t\%n + 1$ \vskip0.12cm
\State \quad  $\mU^t = \big[
    - \vg_{i_t}(\vz_{i_t}^t),~~ 
    \vg_{i_t}(\vx^{t+1})
\big]$ \vskip0.12cm
\State \quad
$\mV^t = \big[\vg_{i_t}(\vz_{i_t}^t),~~ 
    \vg_{i_t}(\vx^{t+1})\big]$ \vskip0.12cm
\State \quad $\vu^{t+1} = \vu^t - \left(\vg_{i_t}(\vz_{i_t}^t)^\top\vz_{i_t}^{t} - f_{i_t}(\vz_{i_t}^t)\right)\vg_{i_t}(\vz_{i_t}^t) 
 + \left(\vg_{i_t}(\vx^{t+1})^\top\vx^{t+1} - f_{i_t}(\vx^{t+1})\right)\vg_{i_t}(\vx^{t+1})$ \vskip0.12cm
\State \quad $\mH^{t+1} =\mH^t - \vg_{i_t}(\vz_{i_t}^t)\vg_{i_t}(\vz_{i_t}^t)^\top+ \vg_{i_t}(\vx^{t+1})\vg_{i_t}(\vx^{t+1})^\top$ \vskip0.12cm
\State\label{line:update-G} \quad  $\mG^{t+1} =\mG^{t} - \mG^{t}\mU^t(\mI + (\mV^t)^\top\mG^{t}\mU^t)^{-1}(\mV^t)^\top\mG^{t}$ \vskip0.12cm
\State \quad  $\vz_i^{t+1} = \begin{cases}
        \vx^{t+1}, & \text{if~} i=i_t \\
        \vz_i^t, & \text{otherwise}
    \end{cases}$ \vskip0.12cm
\State \textbf{end for}
\end{algorithmic}
\end{algorithm}

where $\vz_i^t\in\BR^d$ is some point related to component $f_i$ at the $t$-th iteration.


\begin{align}\label{eq:ign-update-0}
\vx^{t+1} 
= \left(\sum_{i=1}^n \vg_i(\vz_i^t)\vg_i(\vz_i^t)^\top\right)^{-1}\sum_{i=1}^n \left(\vg_i(\vz_i^t)^\top\vz_i^t -  f_i(\vz_i^t)\right)\vg_i(\vz_i^t).
\end{align}

\begin{align}
\label{eq:update-1}
    \vz_i^{t+1} = \begin{cases}
        \vx^{t+1}, & \text{if~} i=i_t, \\
        \vz_i^t, & \text{otherwise},
    \end{cases}   
\end{align}

\begin{align}\label{eq:note-1}
\vu^t = \sum_{i=1}^n \left(\vg_i(\vz_i^t)^\top\vz_i^t -  f_i(\vz_i^t)\right)\vg_i(\vz_i^t), \qquad  
\mH^t=\sum_{i=1}^n \vg_i(\vz_i^t)\vg_i(\vz_i^t)^\top
\qquad\text{and}\qquad \mG^t = \left(\mH^t\right)^{-1}.
\end{align}

\begin{dfn}
\label{def:series}
We define the following sequence $\{a_t(n,\nu)\}_{t\geq0}$ for given $n\in\BN^+$ and $\nu\in(0, 1]$:
\begin{align}
\label{eq:series}
a_t(n,\nu)\triangleq
\begin{cases}
    1,~~~~&t=0,\\[0.15cm]
    % \frac{1}{2(1+\nu)}~~~~&t=1\\
    \displaystyle{\frac{1}{2(1+\nu)n}\left(\sum_{j=0}^{t-1}(a_j(n, \nu))^{1+\nu} + n - t\right)},~~~~& 1\leq t\leq n,\\[0.6cm]
     \displaystyle{\frac{1}{2(1+\nu)n}\sum_{j=t-n}^{t-1}(a_j(n, \nu))^{1+\nu}},~~~~&t> n.
\end{cases}
\end{align}
\end{dfn}

