statement.raw_tex:
\begin{thm}
\label{thm:holder-IGN-1}
{
    Under Assumptions \ref{asm:L-f}, \ref{asm:holder-g} and \ref{asm:b-J-sing}, running \IGN~(Algorithm \ref{alg:IGN-1}) with initialization $\vx^0\in\BR^d$, $\mH^0 = \mJ(\vx^0)^\top\mJ(\vx^0)$ and $\mG^0=(\mH^0)^{-1}$ such that
    \begin{align*}
    \Norm{\vx^0 - \vx^*}\leq \left(\frac{\mu^2}{4L_f\fH_\nu n}\right)^{1/\nu},
    \end{align*} 
    we have $\mH^t \succeq (\mu^2/2)\mI$ and $\sigma_{\min}(\mI + (\mV^t)^\top\mG^{t}\mU^t)>0$ for all $t\geq 0$.
    Additionally, there exists sequence $\{r^t\}$ such that $\Norm{\vx^t-\vx^*}\leq r_t$ and it holds

    \begin{align*}
     r_{t+1}\leq  c^{(1+\nu)^{\left(\floor{{t}/{n}}-1\right)}}r_t \qquad\text{with}\qquad c = 1- \frac{1}{n}\left(1-\left(\frac{1}{2 
  (1+\nu)}\right)^{(1+\nu)}\right)
    \end{align*}
    for all $t\geq n$.
}
\end{thm}

