proof.raw_tex:
\begin{prop}\label{prop:b-JJ-sing}
Under Assumption \ref{asm:b-J-sing}, it holds that
\begin{align}\label{eq::b-JJ-sing}
    \sigma_{\min} (\mJ(\vx^*)^\top \mJ(\vx^*)) = \mu^2 > 0.
\end{align}
\end{prop}

\begin{lem}
\label{le:L-JJ}
{
    Under Assumptions \ref{asm:L-f} and \ref{asm:holder-g}, we have 
    \begin{align*}
    \Norm{\mJ(\vy)^\top\mJ(\vy) - \mJ(\vx)^\top\mJ(\vx)} & \leq 2L_f\fH_\nu\Norm{\vy-\vx}^\nu
    \end{align*}
    and
    \begin{align*}
    \Norm{\vg_i(\vy)\vg_i(\vy)^\top - \vg_i(\vx)\vg_i(\vx)^\top}   \leq 2L_f\fH_\nu\Norm{\vy-\vx}^\nu
    \end{align*}
    for all $\vx, \vy\in\BR^n$ and $i \in [n]$.
}
\end{lem}

\begin{lem}
\label{le:lb-Ht-new-1}
Under Assumptions \ref{asm:L-f}, \ref{asm:holder-g} and \ref{asm:b-J-sing}, running \IGN~(Algorithm \ref{alg:IGN-1}) with $\mH^0 = \mJ(\vx^0)^\top\mJ(\vx^0)$ and~$\mG^0=(\mH^0)^{-1}$ holds that
\begin{align*}
    \sigma_{\min}(\mH^t) \geq \mu^2 - 2L_f\fH_\nu\sum_{i=1}^n \Norm{\vz_i^t - \vx^*}^\nu
\end{align*}
for all $t\geq 0$.
\end{lem}

\begin{lem}
    \label{le:H-con}
    \textnormal{(H\"older continuity of each gradient)} Under Assumption \ref{asm:holder-g}, it satisfies that
    \begin{align}
        \Norm{\vg_i(\vy)-\vg_i(\vx)}\leq \fH_\nu\Norm{\vy-\vx}^\nu,
    \end{align}
    for any $\vx, \vy\in\BR^d$, and $i\in[n]$.
\end{lem}

\begin{proof}
    We denote
    \begin{align*}
    \Tilde{\mJ} = \begin{bmatrix}
        (\vg_1(\vy)-\vg_1(\vx))^\top \\
        \vdots \\
        (\vg_n(\vy)-\vg_n(\vx))^\top 
    \end{bmatrix}\in\BR^{n\times d} \qquad\text{with}\qquad \vg_i(\vx)=\nabla f_i(\vx)
    \end{align*}
    and let $\ve_i\in\BR^{n}$ be the $i$-th standard basic vector in $n$-dimensional Euclidean space. 
    Then the facts~$\Tilde{\mJ}=\mJ(\vy)-\mJ(\vx)$ and $\Tilde{\mJ}^\top \ve_i=\vg_i(\vy)-\vg_i(\vx)$ imply we have
    \begin{align*}
    \Norm{\vg_i(\vy)-\vg_i(\vx)}
    \leq \|\Tilde{\mJ}^\top\|\Norm{\ve_i} = 
    \|\Tilde{\mJ}\|=\Norm{\mJ(\vy)-\mJ(\vx)}\leq \fH_\nu\Norm{\vy-\vx}^\nu,
    \end{align*}
    where the last step is based on the H\"older continuouity of $\mJ(\cdot)$.
\end{proof}

\begin{lem}
\label{le:power-bound}
\textnormal{(Bound for H\"older-continuous function)} Under Assumption \ref{asm:holder-g}, we have
    \begin{align}
        f_i(\vy) - f_i(\vx) - \vg_i(\vx)^\top(\vy-\vx) \leq \frac{\fH_\nu}{1 + \nu}\Norm{\vy-\vx}^{1+\nu},
    \end{align}
    for any $\vx, \vy\in\BR^d$ and  $i\in[n]$.
\end{lem}

\begin{proof}
    Following the proof of \cite{grapiglia2017regularized, grapiglia2019accelerated}, we have
    \begin{align*}
        f_i(\vy) - f_i(\vx) - \vg_i(\vx)^\top(\vy - \vx)
        & = \int_{t=0}^1 \vg_i(\vx + t(\vy - \vx))^\top(\vy - \vx)\text{d}t - \vg_i(\vx)^\top(\vy - \vx)\\
        & = \int_{t=0}^1 \left(\vg_i(\vx + t(\vy - \vx)) - \vg_i(\vx)\right)^\top(\vy - \vx)\text{d}t\\
        & \leq \int_{t=0}^1 \Norm{\vg_i(\vx + t(\vy - \vx)) - \vg_i(\vx)}\Norm{\vy - \vx}\text{d}t\\
        & \leq \int_{t=0}^1\fH_\nu t^\nu\Norm{\vy - \vx}^{1+\nu}\text{d}t\\
        & = \fH_\nu \Norm{\vy - \vx}^{1+\nu}\int_{t=0}^1 t^\nu\text{d}t\\
        & = \frac{\fH_\nu}{1 + \nu} \Norm{\vy - \vx}^{1+\nu},
    \end{align*}
    where the first inequality comes from Cauchy-Schwarz inequality, and the second one comes from Lemma \ref{le:H-con} that each gradient is H\"older continuous.
\end{proof}

\begin{lem}
\label{le:b-grad}
    \textnormal{(Bound for Jacobian and gradient)} Under Assumption \ref{asm:L-f}, we have
    \begin{align*}
        \Norm{\vg_i(\vx)}\leq\Norm{\mJ(\vx)}\leq L_f
    \end{align*}
    for all $ \vx\in\BR^d$ and $i\in [n]$.
\end{lem}

\begin{proof}

    For all $\vx, \vv\in\BR^d$, we have
    \begin{align*}
        \mJ(\vx)\vv =\lim_{h\to0}\frac{\vf(\vx+h\vv)-\vf(\vx)}{h}.
    \end{align*}
    Taking the spectral norm on both sides, we have
    \begin{align*}
        \Norm{\mJ(\vx)\vv}
        & = \lim_{h\to0}\frac{\Norm{\vf(\vx+h\vv)-\vf(\vx)}}{\vert h\vert}\\
        & \leq \lim_{h\to0}\frac{L_f\Norm{\vx+h\vv-\vx}}{\vert h\vert}\\
        & = \lim_{h\to0}\frac{L_f\vert h\vert\Norm{\vv}}{\vert h\vert}\\
        & = L_f\Norm{\vv},
    \end{align*}
    where the inequality comes from Assumption \ref{asm:L-f}. 

    Therefore, for all $\vx\in\BR^d$ it holds
    \begin{align*}
    \Norm{\mJ(\vx)}=\sup_{\vv\in\BR^d}\frac{\Norm{\mJ(\vx)\vv}}{\Norm{\vv}}\leq L_f.
    \end{align*}
    Let $\ve_i\in\BR^{n}$ be the $i$-th standard basic vector in $n$-dimensional Euclid space, then we have 

    \begin{align*}
    \Norm{\vg_i(\vx)} = \Norm{\mJ^\top \ve_i} \leq \Norm{\mJ}\Norm{\ve_i}=\Norm{\mJ(\vx)}\leq L_f
    \end{align*}
    for all $i\in[n]$.
\end{proof}

\begin{lem}
\label{le:s-mono-000} The sequence $\{a_t(n, \nu)\}_{t\geq 0}$ satisfies 
\begin{align*}
    a_t(n, \nu) \leq 1 
\end{align*}
for all $t\geq 0$. 
\end{lem}

\begin{proof}
\textbf{Part I:}
We first use induction to prove $a_t(n, \nu) \leq 1$ for all $t=0,1\dots,n$.
For the induction base, we can verify that $a_0(n, \nu) = 1 \leq 1$.  For the induction step, we assume 
\begin{align*}
a_j(n,\nu) \leq 1    
\end{align*}
holds for all $j=1,\dots,t-1$ such that $t\leq n$.
Then we have
\begin{align*}
        a_t(n,\nu) = \frac{1}{2(1+\nu)n}\left(\sum_{j=0}^{t-1}(a_j(n,\nu))^{1+\nu} + n - t\right) \leq \frac{1}{2(1+\nu)n}\left(t + n - t\right) = \frac{1}{2(1+\nu)}\leq 1,
\end{align*}
where the first inequality is based on the induction hypothesis and the last inequality is based on the setting $\nu\in(0,1]$. This finishes the induction. 

\textbf{Part II:} We then use induction to prove $a_t(n, \nu) \leq 1$ for all $t\geq n+1$. For the induction base, we can verify that
\begin{align*}
    a_{n+1}(n,\nu) = \frac{1}{2(1+\nu)n}\sum_{j=1}^{n}(a_j(n, \nu))^{1+\nu} \leq \frac{1}{2(1+\nu)n}\cdot n = \frac{1}{2(1+\nu)} \leq 1,
\end{align*}
where the first inequality is based on $a_t(n, \nu) \leq 1$ for all $t\leq n$ (which have shown in Part I), and the last inequality is based on the setting $\nu \in (0, 1]$. For the induction step, we assume
\begin{align*}
    a_{n+1}(n,\nu) \leq 1
\end{align*}
holds for all $j=n+2,\dots,t-1$ such that $t\geq n+3$. Then we have
\begin{align*}
    a_{t}(n,\nu) = \frac{1}{2(1+\nu)n}\sum_{j=t-n}^{t-1}(a_j(n, \nu))^{1+\nu} \leq \frac{1}{2(1+\nu)n}\cdot n = \frac{1}{2(1+\nu)} \leq 1,
\end{align*}

where the first inequality is based on the induction hypothesis and the last inequality is based on the setting $\nu \in (0, 1]$. This finishes the induction.

Combining the results of above two parts, we finish the proof of this lemma.
\end{proof}

\begin{lem}
\label{le:s-mono}The sequence $\{a_t(n, \nu)\}_{t\geq 0}$ satisfies 
\begin{align*}
    a_{t}(n, \nu) \geq a_{t+1}(n, \nu) 
\end{align*}
for all $t\geq 0$. 

\end{lem}

\begin{proof}
\textbf{Part I:} For $t=0$, the fact $\nu\in(0, 1]$ means
\begin{align*}
    a_1(n, \nu) = \frac{1}{2(1+\nu)} \leq 1 = a_0(n, \nu).
\end{align*}
\textbf{Part II:}
For all $t=1,\dots,n-1$, we have
\begin{align*}
        & a_{t+1}(n, \nu) - a_{t}(n, \nu) \\
        & = \frac{1}{2(1+\nu)n}\left(\sum_{j=0}^{t}(a_j(n, \nu))^{1+\nu} + n - t - 1\right) - \frac{1}{2(1+\nu)n}\left(\sum_{j=0}^{t-1}(a_j(n, \nu))^{1+\nu} + n - t\right)\\
        & = \frac{1}{2(1+\nu)n}\left((a_{t}(n, \nu))^{1+\nu} - 1\right)  \leq 0,
\end{align*}     
where the last inequality is based on Lemma \ref{le:s-mono-000}. This indicates $a_{t+1}\leq a_{t}$ for $t=1,\dots,n-1$. 

\textbf{Part III:} For all $t\geq n$, we use induction to prove $a_{t+1}(n, \nu)\leq a_{t}(n, \nu)$. 
For the induction base, we can verify that
    \begin{align*}
        & a_{n+1}(n, \nu) - a_n(n, \nu) \\
        & = \frac{1}{2(1+\nu)n}\sum_{j=1}^{n}(a_j(n, \nu))^{1+\nu} - \frac{1}{2(1+\nu)n}\left(\sum_{j=1}^{n-1}(a_j(n, \nu))^{1+\nu} + 1\right)\\
        & = \frac{1}{2(1+\nu)n}\left((a_n(n, \nu))^{1+\nu} - 1\right)\\
        & \leq 0,
    \end{align*}
    where the last inequality is based on Lemma \ref{le:s-mono-000}. 

    For the induction step, we assume
\begin{align*}
    a_{j+1}(n, \nu) \leq a_{j}(n, \nu)
\end{align*}
holds for all $j = n+1, \cdots, t-1$ such that $t\geq n+2$. Then we have
    \begin{align*}
        & a_{t+1}(n, \nu) - a_{t}(n, \nu) \\
         =&  \frac{1}{2(1+\nu)n}\sum_{j=t-n + 1}^{t}(a_j(n, \nu)) ^{1+\nu} - \frac{1}{2(1+\nu)n}\sum_{j=t-n}^{t-1}(a_j(n, \nu))^{1+\nu} \leq 0,
    \end{align*}
where the inequality is based on the induction hypothesis and the fact $a_{t+1}(n, \nu) \leq a_{t}(n, \nu)$ for all~$t \leq n - 1$ (which have shown in Part I).

Combining the results of above three parts, we finish the proof of this lemma.
\end{proof}

\begin{lem}
\label{le:n-qua-con}
     For the sequence $\{a_t(n, \nu)\}_{t\geq 0}$, we have
    \begin{align*}
    a_t(n, \nu) \leq \frac{1}{2(1+\nu)}(a_{t-n}(n, \nu))^{1+\nu}
    \end{align*}
    for all $t\geq n$.
\end{lem}

\begin{proof}
    For all $t\geq n$, the definition of $a_t(n, \nu)$ implies
    \begin{align*}
    & a_t(n, \nu) = \frac{1}{2(1+\nu)n}\left(\sum_{j=t-n}^{t-1}(a_j(n, \nu))^{1+\nu}\right)  \\
    & \leq \frac{1}{2(1+\nu)} \max\{(a_{t-n}(n, \nu))^{1+\nu},\cdots, (a_{t-1}(n, \nu))^{1+\nu}\}.
    \end{align*}
    Additionally, Lemma \ref{le:s-mono} implies for all $t\geq n$, we have
    \begin{align*}
    \max\{(a_{t-n}(n, \nu))^{1+\nu},\cdots, (a_{t-1}(n, \nu))^{1+\nu}\} = (a_{t-n}(n, \nu))^{1+\nu}, \quad t\geq n.
    \end{align*}
    Combining above results, we achieve
    \begin{align*}
    a_t(n, \nu) \leq \frac{1}{2(1+\nu)}(a_{t-n}(n, \nu))^{1+\nu}
    \end{align*}
    for all $t\geq n$.
\end{proof}

\begin{lem}
\label{le:linear-con} For the sequence $\{a_t(n, \nu)\}_{t\geq 0}$, we have 
\begin{align*}
a_{t+1}(n, \nu)\leq c_0 a_t(n, \nu)
\end{align*}
for all $t\geq n$, where
\begin{align*}
    c_0 = 1- \frac{1}{n}\left(1-\left(\frac{1}{2(1+\nu)}\right)^{1+\nu}\right).
\end{align*}
\end{lem}

\begin{proof}
    For all $t\geq n$, we have
    \begin{align}\label{eq:lemma9-ieq}
    a_t(n, \nu) \leq \frac{1}{2(1+\nu)}(a_{t-n}(n, \nu))^{1+\nu} \leq \frac{1}{2(1+\nu)}a_{t-n}(n, \nu), 
    \end{align}
    where the first inequality is based on Lemma \ref{le:n-qua-con} and the second one is based on Lemma \ref{le:s-mono-000}.

    Then we also have 
    \begin{align*}\small\begin{split}
        a_{t+1} 
        & = \frac{1}{2(1+\nu)n}\left(\sum_{j=t-n+1}^{t}(a_j(n, \nu))^{1+\nu}\right)\\
        & \leq \frac{1}{2(1+\nu)n}\left(\left(\frac{1}{2(1+\nu)}\right)^{1+\nu}(a_{t-n}(n, \nu))^{1+\nu} + \sum_{j=t-n+1}^{t-1}(a_j(n, \nu))^{1+\nu}\right)\\
        & = \frac{1}{2(1+\nu)n}\left(\left(\frac{1}{2(1+\nu)}\right)^{1+\nu}(a_{t-n}(n, \nu))^{1+\nu} + \sum_{j=t-n+1}^{t-1}(a_j(n, \nu))^{1+\nu} + (a_{t-n}(n, \nu))^{1+\nu} - (a_{t-n}(n, \nu))^{1+\nu} \right)\\
        & = a_{t}(n, \nu) + \frac{1}{2(1+\nu)n}\left(\left(\frac{1}{2(1+\nu)}\right)^{1+\nu}(a_{t-n}(n, \nu))^{1+\nu} - (a_{t-n}(n, \nu))^{1+\nu} \right)\\
        & = a_{t}(n, \nu) - \frac{1}{2(1+\nu)n}\left(1-\left(\frac{1}{2(1+\nu)}\right)^{1+\nu}\right)(a_{t-n}(n, \nu))^{1+\nu}\\
        & \leq a_{t}(n, \nu) - \frac{1}{n}\left(1-\left(\frac{1}{2(1+\nu)}\right)^{1+\nu}\right)a_t(n, \nu)\\
        & = \left(1- \frac{1}{n}\left(1-\left(\frac{1}{2(1+\nu)}\right)^{1+\nu}\right)\right)a_t(n, \nu),
     \end{split}
    \end{align*}
    for all $t\geq n$, where the first inequality is based on equation (\ref{eq:lemma9-ieq}) and the last inequality is based on Lemma \ref{le:n-qua-con}. This finish the proof.
\end{proof}

\begin{lem}
\label{le:imp-c} For the sequence $\{a_t(n, \nu)\}_{t\geq 0}$, if there exists $c_1\in(0,1)$ and $t_0\geq 0$ such that
\begin{align}\label{eq:ieq-t0n2n}
a_{t+1}(n, \nu) \leq c_1 a_t(n, \nu)
\end{align}
for all $t\geq t_0 + n$, 
then we have
\begin{align*}
a_{t+1}(n, \nu) \leq c_1^{1+\nu} a_t(n, \nu)
\end{align*}
for all $t\geq t_0 + 2n$.
\end{lem}

\begin{proof}
    For all  $t\geq t_0 + 2n$, we have
    \begin{align*}
        & a_{t+1} (n, \nu)
         = \frac{1}{2(1+\nu)n}\sum_{j=t-n+1}^{t}(a_j(n, \nu))^{1+\nu} \\
        & \leq \frac{1}{2(1+\nu)n}\sum_{j=t-n}^{t-1}c_1^{1+\nu}(a_j(n, \nu))^{1+\nu} = c_1^{1+\nu} a_t(n, \nu),
    \end{align*}
    where the inequality is based on equation (\ref{eq:ieq-t0n2n}).
\end{proof}

\begin{lem}
\label{le:super-con} For the sequence $\{a_t(n, \nu)\}_{t\geq 0}$,
we have the superlinear convergence
\begin{align*}
a_{t+1}(n, \nu) \leq c^{(1+\nu)^{\left(\floor{\frac{t-1}{n}}-1\right)}}a_t(n, \nu) 
\end{align*}
for all $t\geq n$, where
\begin{align*}
    c = 1- \frac{1}{n}\left(1-\left(\frac{1}{2(1+\nu)}\right)^{1+\nu}\right).
\end{align*}
\begin{proof}
    According to Lemma \ref{le:linear-con}, we have
    \begin{align*}
        a_{t+1}(n, \nu)\leq c a_t(n, \nu) 
        \quad \text{for all}~~t \geq n.
    \end{align*}
    According to Lemma \ref{le:imp-c}, we have
    \begin{align*}
        a_{t+1}(n, \nu) & \leq c^{1+\nu} a_t(n, \nu) \quad \text{for all}~~t \geq 2n,\\
        a_{t+1}(n, \nu) & \leq c^{(1+\nu)^2} a_t(n, \nu) \quad \text{for all}~~t \geq 3n,\\
        a_{t+1}(n, \nu) & \leq c^{(1+\nu)^3} a_t(n, \nu) \quad \text{for all}~~t \geq 4n,\\
        \cdots &
    \end{align*}
    which implies
    \begin{align*}
        a_{t+1}(n, \nu) \leq c^{(1+\nu)^{\left(\lfloor {t}/{n}  \rfloor-1\right)}}a_t(n, \nu)
    \end{align*}
    for all $t \geq n$.

    The superlinear convergence of the sequence $\{a_t(n, \nu)\}_{t\geq 0}$ can be verify by the fact
    \begin{align*}
        \lim_{t\to\infty}c^{(1+\nu)^{\left(\lfloor {t}/{n}  \rfloor-1\right)}}=0.
    \end{align*}
    Hence, we finish the proof.
\end{proof}
\end{lem}

\begin{proof}
We denote the singular value decomposition of $\mJ(\vx^*)$ as
    \begin{align*}
        \mJ(\vx^*) = \mP\mD\mQ^\top,
    \end{align*}
    where $\mP\in\BR^{n\times d}, \mQ\in\BR^{d\times d}$ are (column) orthogonal matrices and $\mD\in\BR^{d\times d}$ is diagonal matrix with the smallest diagonal entry of $\mu>0$.
    Therefore, we have
    \begin{align*}
        \mJ(\vx^*)^\top \mJ(\vx^*) = \mQ\mD^2\mQ^\top,
    \end{align*}
    which means the smallest singular value of $\mJ(\vx^*)^\top \mJ(\vx^*)$ is equal to the smallest value of $\mD^2$, which is $\mu^2$. Therefore, we have
    \begin{align*}
        \sigma_{\min}(\mJ(\vx^*)^\top\mJ(\vx^*)) \geq \mu^2.
    \end{align*}
\end{proof}

\begin{proof}
    The Jacobian holds that
    \begin{align*}
        \Norm{\mJ(\vy)^\top\mJ(\vy) - \mJ(\vx)^\top\mJ(\vx)}
        & = \Norm{\mJ(\vy)^\top\mJ(\vy) - \mJ(\vx)^\top\mJ(\vy) + \mJ(\vx)^\top\mJ(\vy) - \mJ(\vx)^\top\mJ(\vx)}\\
        & \leq \Norm{\left(\mJ(\vy)-\mJ(\vx)\right)^\top\mJ(\vy)} + \Norm{\mJ(\vx)^\top\left(\mJ(\vy) - \mJ(\vx)\right)}\\
        & \leq \Norm{\mJ(\vy)}\Norm{\mJ(\vy)-\mJ(\vx)} + \Norm{\mJ(\vx)}\Norm{\mJ(\vy)-\mJ(\vx)}\\
        & \leq 2L_f\fH_\nu\Norm{\vy-\vx}^\nu,
    \end{align*}
    where the first inequality comes from triangular inequality, the second inequality comes from property of norm, and the last inequality is based on Lemma \ref{le:b-grad} and Assumption \ref{asm:holder-g}. 

    For all $j\in[n]$, the gradient holds that
    \begin{align*}
        \Norm{\vg_i(\vy)\vg_i(\vy)^\top\!- \vg_i(\vx)\vg_i(\vx)^\top}
        & = \Norm{\vg_i(\vy)\vg_i(\vy)^\top\!- \vg_i(\vx)\vg_i(\vy)^\top + \vg_i(\vx)\vg_i(\vy)^\top\!- \vg_i(\vx)\vg_i(\vx)^\top}\\
        & \leq \Norm{\left(\vg_i(\vy)-\vg_i(\vx)\right)\vg_i(\vy)^\top} + \Norm{\vg_i(\vx)\left(\vg_i(\vy)-\vg_i(\vx)\right)^\top}\\
        & \leq \Norm{\vg_i(\vy)}\Norm{\vg_i(\vy)-\vg_i(\vx)} + \Norm{\vg_i(\vx)}\Norm{\vg_i(\vy)-\vg_i(\vx)}\\
        & \leq 2L_f\fH_\nu\Norm{\vy-\vx}^\nu,
    \end{align*}
    where the first inequality comes from triangular inequality, the second inequality comes from property of norm, and the last inequality is based on Lemma \ref{le:H-con} and \ref{le:b-grad}.
\end{proof}

\begin{proof}
    We have
    \begin{align*}
        \Norm{\mH^t - \mJ(\vx^*)^\top\mJ(\vx^*)} &= \Norm{\sum_{i=1}^n\vg_i(\vz_i^t)\vg_i(\vz_i^t)^\top - \sum_{i=1}^n\vg_i(\vx^*)\vg_i(\vx^*)^\top}\\
        & \leq \sum_{i=1}^n\Norm{\vg_i(\vz_i^t)\vg_i(\vz_i^t)^\top - \vg_i(\vx^*)\vg_i(\vx^*)^\top}\\
        & \leq \sum_{i=1}^n 2L_f\fH_\nu\Norm{\vz_i^t - \vx^*}^\nu,
    \end{align*}
    where the first inequality comes from the triangle inequality and the second inequality is based on Lemma \ref{le:L-JJ}. 
    Thus, we have
     \begin{align*}
         \mH^{t}-\mJ(\vx^*)^{\top}\mJ(\vx^*)\succeq - \sum_{i=1}^n 2L_f\fH_\nu\Norm{\vz_i^t - \vx^*}^\nu \cdot\mI, 
     \end{align*}
    which implies that
    \begin{align*}
        \sigma_{\min}(\mH^t) \geq \sigma_{\min}(\mJ(\vx^*)^\top\mJ(\vx^*)) - \sum_{i=1}^n 2L_f\fH_\nu\Norm{\vz_i^t - \vx^*}^\nu = \mu^2 - 2L_f\fH_\nu\sum_{i=1}^n \Norm{\vz_i^t - \vx^*}^\nu,
    \end{align*}
    where the last step is based on Proposition \ref{prop:b-JJ-sing}.
\end{proof}

We first show the update
\begin{align*}
\mG^{t+1} =\mG^{t} - \mG^{t}\mU^t(\mI + (\mV^t)^\top\mG^{t}\mU^t)^{-1}(\mV^t)^\top\mG^{t}    
\end{align*}
in \IGN~method (Line \ref{line:update-G} of Algorithm \ref{alg:IGN-1}) is well-defined if the matrices $\mH^t$ and $\mH^{t+1}$ are non-singular.


\begin{lem}
\label{le:via-update}
    Following the setting of Theorem \ref{thm:holder-IGN-1}, if the matrices $\mH^t$ and $\mH^{t+1}$ are non-singular, then the matrix $\mI + {\mV^t}^\top\mG^{t}\mU^t$ is also non-singular, where
    \begin{align*}
    \mU^t = \begin{bmatrix}
        - \vg_{i_t}(\vz_{i_t}^t) \!& 
        \vg_{i_t}(\vx^{t+1})
    \end{bmatrix}\in\BR^{d\times 2},~~
    \mV^t = \begin{bmatrix}
        \vg_{i_t}(\vz_{i_t}^t) \!& 
        \vg_{i_t}(\vx^{t+1})
    \end{bmatrix}\in\BR^{d\times 2}~~\text{and}~~i_t ={t\%n} + 1.
    \end{align*}
\end{lem}

\begin{proof}
    The recursion of $\mH^t$ and the definition of $\mU^t$ and $\mV^t$ imply
    \begin{align*}
        \mH^{t+1} = \mH^t - \vg_{i_t}(\vz_{i_t}^t)\vg_{i_t}(\vz_{i_t}^t)^\top + \vg_{i_t}(\vx^{t+1})\vg_{i_t}(\vx^{t+1})^\top = \mH^t + \mU^t{\mV^t}^\top.
    \end{align*}
    Since we assume matrices $\mH^t$ and $\mH^{t+1}$ are non-singular, applying the matrix determinant lemma \cite[Section 9.1.2]{petersen2008matrix} on above equation leads to
    \begin{align*}
        \det(\mH^{t+1})=\det(\mH^t + \mU^t{\mV^t}^\top) = \det(\mI + {\mV^t}^\top(\mH^t)^{-1}\mU^t)\det(\mH^t).
    \end{align*}
    Then the definition $\mG^t={\mH^t}^{-1}$ implies
    \begin{align*}
        \det(\mI + {\mV^t}^\top\mG^t\mU^t) = \det(\mI + {\mV^t}^\top{\mH^t}^{-1}\mU^t) \neq 0
    \end{align*}
    which finish the proofs.
\end{proof}

Then we show the non-singular assumption on $\{\mH^j\}_{j=0}^t$ can upper bound the distance $\Norm{\vx^{t+1} - \vx^*}$.


\begin{lem}\label{le:main-iter-1} 
Under Assumptions \ref{asm:L-f} and \ref{asm:holder-g}, we
assume matrices $\{\mH^j\}_{j=0}^t$ are non-singular and run \IGN~(Algorithm \ref{alg:IGN-1}), then it holds
\begin{align*}
    \Norm{\vx^{t+1} - \vx^*}
     \leq \frac{L_f\fH_\nu}{1 
     +\nu}\Norm{\mG^t}\sum_{i=1}^n\Norm{\vz_i^t-\vx^*}^{1+\nu},
    \end{align*}
    where $\mG^t=\left(\mH^t\right)^{-1}$.
\end{lem}

\begin{proof}
    Subtracting the term $\vx^*$ on both sides of equation (\ref{eq:ign-update-0}), we have
    \begin{align*}
    \vx^{t+1} - \vx^*
    & = \mG^t\left(\sum_{i=1}^n \vg_i(\vz_i^t)\vg_i(\vz_i^t)^\top(\vz_i^t-\vx^*) - \sum_{i=1}^n f_i(\vz_i^t)\vg_i(\vz_i^t)\right)\\
    & = \mG^t\left(\sum_{i=1}^n \vg_i(\vz_i^t)\vg_i(\vz_i^t)^\top(\vz_i^t-\vx^*) - \sum_{i=1}^n f_i(\vz_i^t)\vg_i(\vz_i^t) + \sum_{i=1}^n f_i(\vx^*)\vg_i(\vz_i^t)\right)\\
    & = \mG^t\sum_{i=1}^n\left( \vg_i(\vz_i^t)^\top(\vz_i^t-\vx^*) - f_i(\vz_i^t) + f_i(\vx^*)\right)\vg_i(\vz_i^t).
    \end{align*}

    Taking the norm on the both sides of above results, we have
    \begin{align*}
    \Norm{\vx^{t+1} - \vx^*}
    & = \Norm{\mG^t\sum_{i=1}^n\left( \vg_i(\vz_i^t)^\top(\vz_i^t-\vx^*) - f_i(\vz_i^t) + f_i(\vx^*)\right)\vg_i(\vz_i^t)}\\
    & \leq \Norm{\mG^t}\Norm{\sum_{i=1}^n\left( \vg_i(\vz_i^t)^\top(\vz_i^t-\vx^*) - f_i(\vz_i^t) + f_i(\vx^*)\right)\vg_i(\vz_i^t)}\\
    & \leq \frac{L_f\fH_\nu}{1 + \nu}\Norm{\mG^t}\sum_{i=1}^n\Norm{\vz_i^t-\vx^*}^{1+\nu}
    \end{align*}    
    where the first inequality comes from the property of matrix norm, the second inequality is based on Lemma \ref{le:power-bound} and \ref{le:b-grad}.
\end{proof}

We split the results of Theorem \ref{thm:holder-IGN-1} into two parts (i.e., Theorem \ref{thm:holder-IGN-1-1} and \ref{thm:holder-IGN-1-2}) and provide their proofs as follows.
Our analysis is based on the properties of our the auxiliary sequence constructed in Section \ref{sec:series}.


\begin{thm}
\label{thm:holder-IGN-1-1}
    Under the Assumption \ref{asm:L-f}, \ref{asm:holder-g} and \ref{asm:b-J-sing}, we run \IGN~(Algorithm \ref{alg:IGN-1}) with initialization $\vx^0\in\BR^d$ and~$\mH^0=\mJ(\vx^0)^\top\mJ(\vx^0)$ such that
    \begin{align*}
    \Norm{\vx^0 - \vx^*}\leq \left(\frac{\mu^2}{4L_f\fH_\nu n}\right)^{{1}/{\nu}},
    \end{align*} 
    then it holds 
    \begin{align*}
    \sigma_{\min}(\mI + (\mV^t)^\top (\mH^t)^{-1}\mU^t) > 0,\quad
    \mH^t \succeq \frac{\mu^2}{2}\mI\quad
    \text{and}\quad
    \Norm{\vx^{t}-\vx^*}\leq a_{t+1}(n, \nu)\Norm{\vx^0-\vx^*}
    \end{align*}
    for all $t \geq 0$, where sequence $\{a_t(n, \nu)\}_{t\geq 0}$ is defined in equation (\ref{eq:series}). 
\end{thm}

\begin{proof}

We first show
\begin{align}\label{eq:Hxtxstar0}
\mH^t \succeq \frac{\mu^2}{2}\mI\qquad
\text{and}\qquad
\Norm{\vx^{t}-\vx^*}\leq a_{t+1}(n, \nu)\Norm{\vx^0-\vx^*}
\end{align}
holds for all $t\geq 0$. We split the proof of results (\ref{eq:Hxtxstar0}) into the following three parts.

\textbf{Part I:} For $t=0$, 
the initialization and the fact $a_0=1$ leads to 
\begin{align*}
 \Norm{\vx^0 - \vx^*} = a_0(n, \nu)\Norm{\vx^0 - \vx^*}.
\end{align*}


\textbf{Part II:} For all $t=0,\cdots, n-1$, we use induction to prove the results of 
\begin{align}\label{eq:Hxtxstar}
\mH^t \succeq \frac{\mu^2}{2}\mI\qquad
\text{and}\qquad
\Norm{\vx^{t+1}-\vx^*}\leq a_{t+1}(n, \nu)\Norm{\vx^0-\vx^*}.
\end{align}
For the induction base, we can apply Lemma \ref{le:lb-Ht-new-1} to verify
\begin{align*}
    \sigma_{\min}(\mH^0) &\geq  \mu^2 - 2L_f\fH_\nu\sum_{i=1}^n \Norm{\vz_i^0 - \vx^*}^\nu\\
    & = \mu^2 - 2L_f\fH_\nu\sum_{i=1}^n \Norm{\vx^0 - \vx^*}^\nu\\
    & \geq \mu^2 - 2L_f\fH_\nu n \frac{\mu^2}{4L_f\fH_\nu n}\\
    & = \mu^2 - \frac{\mu^2}{2}\\
    & = \frac{\mu^2}{2}.
\end{align*}


This implies
\begin{align}\label{eq:boundG0}
\mH^0 \succeq \frac{\mu^2}{2} \qquad \text{and}\qquad
\Norm{\mG^0} = \Norm{(\mH^0)^{-1}} \leq \frac{2}{\mu^2}.
\end{align}
According to Lemma \ref{le:main-iter-1}, we have
\begin{align*}
    \Norm{\vx^1 - \vx^*} 
    &\leq \frac{L_f\fH_\nu}{1+\nu}\Norm{\mG^0}\sum_{i=1}^n\Norm{\vz_i^0-\vx^*}^{1+\nu}\\
    & \leq \frac{L_f\fH_\nu}{1+\nu}\cdot\frac{2}{\mu^2}\cdot\sum_{i=1}^n\Norm{\vz_i^0-\vx^*}^{1+\nu}\\
    & = \frac{L_f\fH_\nu}{1+\nu}\cdot\frac{2}{\mu^2}\cdot n\Norm{\vx^0-\vx^*}^{1+\nu}\\
    & \leq \frac{nL_f\fH_\nu}{1+\nu}\cdot\frac{2}{\mu^2}\cdot\frac{\mu^2}{4L_f\fH_\nu n}\Norm{\vx^0-\vx^*}\\
    & = \frac{1}{2(1+\nu)}\Norm{\vx^0-\vx^*}\\
    & = a_1(n, \nu)\Norm{\vx^0 - \vx^*},
\end{align*}
where the first inequality is based on equation (\ref{eq:boundG0}) and the second inequality is based on initial condition. 
Therefore, the induction base holds

For the induction step, we assume
\begin{align*}
    \mH^j \succeq \frac{\mu^2}{2} \mI \qquad\text{and}\qquad\Norm{\vx^{j+1} - \vx^*} \leq a_{j+1}(n, \nu)\Norm{\vx^0 - \vx^*}
\end{align*}
hold for all $j = 2, \cdots, t-1$ such that $t \leq n - 1$. Therefore, the update (\ref{eq:update-1}) means
\begin{align}\label{eq:vziii}
    \vz_i^{t}=
    \begin{cases}
        \vx^i,~~~~&1 \leq i\leq t,\\
        \vx^0,~~~~&t < i \leq n. 
    \end{cases}
\end{align}
The induction hypothesis leads to
\begin{align*}
    \Norm{\vx^j-\vx^*}^{\nu}\leq (a_j(n, \nu))^{\nu}\Norm{\vx^0-\vx^*}^{\nu} \leq  \Norm{\vx^0-\vx^*}^{\nu}\leq \frac{\mu^2}{4L_f\fH_\nu n}, 
\end{align*}
for $j = 1, \cdots, t-1$, where the second is based on Lemma \ref{le:s-mono-000} and the third comes from the initial condition. 
Combining with the result of (\ref{eq:vziii}), we achive
\begin{align*}
    \Norm{\vz_i^{t} - \vx^*}^{\nu} \leq \frac{\mu^2}{4L_f\fH_\nu n}.
\end{align*}

According to Lemma \ref{le:lb-Ht-new-1}, we have
\begin{align*}
    \sigma_{\min}(\mH^{t}) &\geq  \mu^2 - 2L_f\fH_\nu\sum_{i=1}^n \Norm{\vz_i^{t} - \vx^*}^\nu\\
    & \geq \mu^2 - 2L_f\fH_\nu n \frac{\mu^2}{4L_f\fH_\nu n}\\
    & = \mu^2 - \frac{\mu^2}{2}\\
    & = \frac{\mu^2}{2},
\end{align*}

where the second inequality comes from the initial condition.
Therefore, we have
\begin{align*}
    \mH^{t}  \succeq \frac{\mu^2}{2}\mI \qquad \text{and}\qquad
    \Norm{\mG^{t}}  = \Norm{(\mH^{t})^{-1}} \leq \frac{2}{\mu^2}.
\end{align*}
According to Lemma \ref{le:main-iter-1}, we have
\begin{align*}
    \Norm{\vx^{t+1} - \vx^*} 
    & \leq \frac{L_f\fH_\nu }{1+\nu}\Norm{\mG^{t}}\sum_{i=1}^n\Norm{\vz_i^{t}-\vx^*}^{1+\nu}\\
    & \leq \frac{L_f\fH_\nu }{1+\nu}\frac{2}{\mu^2}\sum_{i=1}^n\Norm{\vz_i^{t}-\vx^*}^{1+\nu}\\
    & \leq \frac{2L_f\fH_\nu}{(1+\nu)\mu^2}\left(\sum_{j=1}^{t}\Norm{\vx^{j}-\vx^*}^{1+\nu} + (n - t)\Norm{\vx^0 - \vx^*}^{1+\nu}\right)\\
    & \leq \frac{2L_f\fH_\nu }{(1+\nu)\mu^2}\left(\sum_{j=1}^{t} (a_j(n, \nu))^{1+\nu}\Norm{\vx^0 - \vx^*}^{1+\nu} + (n - t) \Norm{\vx^0 - \vx^*}^{1+\nu}\right)\\
    & \leq \frac{2L_f\fH_\nu }{(1+\nu)\mu^2}\frac{\mu^2}{4L_f\fH_\nu n}\left(\sum_{j=1}^{t}(a_j(n, \nu))^{1+\nu} + n - t\right)\Norm{\vx^0 - \vx^*}\\
    & = \frac{1}{2(1+\nu)n}\left(\sum_{j=1}^{t}(a_j(n, \nu))^{1+\nu} + n - t\right)\Norm{\vx^0 - \vx^*}\\
    & = \frac{1}{2(1+\nu)n}\left(\sum_{j=0}^{t}(a_j(n, \nu))^{1+\nu} + n - t - 1\right)\Norm{\vx^0 - \vx^*}\\
    & = a_{t+1}(n, \nu)\Norm{\vx^0 - \vx^*},
\end{align*}
where the last equality comes from the fact $a_0(n, \nu)=1$. 
Therefore, we finish the induction.


\textbf{Part III:} For all $t \geq n$, we use induction to prove 
\begin{align*}
\mH^t\succeq(\mu^2/2)\mI\qquad\text{and}\qquad\Norm{\vx^{t+1} - \vx^*}\leq a_{t+1}(n, \nu)\Norm{\vx^0 - \vx^*}.    
\end{align*}
For the induction base, we can verify that it holds (from the result of Part II) 
\begin{align*}
\mH^j \succeq \frac{\mu^2}{2}\mI \qquad \text{for all~~} j=0,\dots,n - 1,
\end{align*}
and
\begin{align*}
\Norm{\vx^j-\vx^*}\leq a_j(n, \nu)\Norm{\vx^0-\vx^*} \qquad \text{for all~~} j=1,\dots,n.
\end{align*}
Then we have
\begin{align*}
    \Norm{\vx^j-\vx^*}^{\nu}\leq (a_j(n, \nu))^{\nu}\Norm{\vx^0-\vx^*}^{\nu} \leq \Norm{\vx^0-\vx^*}^{\nu} \leq \frac{\mu^2}{4L_f\fH_\nu n}, \quad \text{for all~~} j=1,\dots,n,
\end{align*}
where the second inequality is based on Lemma \ref{le:s-mono-000} and the third inequality is based on the initial condition.

From Eq.~\ref{eq:update-1}, we have
\begin{align*}
    \vz_i^{n}=\vx^i \qquad\text{for all~~} i\in[n].
\end{align*}

Therefore, we have
\begin{align*}
    \Norm{\vz_i^{n} - \vx^*}^{\nu} \leq \frac{\mu^2}{4L_f\fH_\nu n}, \qquad\text{for all~~} i\in[n].
\end{align*}
According to Lemma \ref{le:lb-Ht-new-1}, we have
\begin{align*}
    \sigma_{\min}(\mH^{n}) &\geq  \mu^2 - 2L_f\fH_\nu\sum_{i=1}^n \Norm{\vz_i^{n} - \vx^*}^\nu\\
    & \geq \mu^2 - 2L_f\fH_\nu n \frac{\mu^2}{4L_f\fH_\nu n}\\
    & \geq \mu^2 - \frac{\mu^2}{2} = \frac{\mu^2}{2},
\end{align*}

which implies
\begin{align*}
    \mH^{n}  \succeq \frac{\mu^2}{2}\mI \qquad\text{and}\qquad
    \Norm{\mG^{n}}  = \Norm{(\mH^{n})^{-1}} \leq \frac{2}{\mu^2}.
\end{align*}
According to Lemma \ref{le:main-iter-1}, we have
\begin{align*}
    \Norm{\vx^{n+1} - \vx^*}
    & \leq \frac{L_f\fH_\nu }{1+\nu}\Norm{\mG^n}\sum_{i=1}^n\Norm{\vz_i^n-\vx^*}^{1+\nu}\\
    & \leq \frac{2L_f\fH_\nu }{(1+\nu)\mu^2}\sum_{i=1}^n\Norm{\vz_i^n-\vx^*}^{1+\nu}\\
    & \leq \frac{2L_f\fH_\nu }{(1+\nu)\mu^2}\left(\sum_{j=1}^n (a_j(n, \nu))^{1+\nu}\Norm{\vx^0 - \vx^*}^{1+\nu}\right)\\
    & \leq \frac{2L_f\fH_\nu }{(1+\nu)\mu^2}\frac{\mu^2}{4L_f\fH_\nu n}\left(\sum_{j=1}^{n}(a_j(n, \nu))^{1+\nu}\right)\Norm{\vx^0-\vx^*}\\
    & = \frac{1}{2(1+\nu)n}\left(\sum_{j=1}^{n}(a_j(n, \nu))^{1+\nu}\right)\Norm{\vx^0-\vx^*}\\
    & = a_{n+1}(n, \nu)\Norm{\vx^0-\vx^*}.
\end{align*}
Hence, we have shown the induction base holds. 

For the induction step, we assume
\begin{align*}
    \mH^j \succeq \frac{\mu^2}{2} \mI \qquad\text{and}\qquad\Norm{\vx^{j+1} - \vx^*} \leq a_{j+1}(n, \nu)\Norm{\vx^0 - \vx^*}
\end{align*}
holds for all $j = n+1, \cdots, t-1$ such that $t \geq n + 2$. Combining results of Part I and II, we have

\begin{align*}
\Norm{\vx^j-\vx^*}\leq a_j(n, \nu)\Norm{\vx^0-\vx^*} \qquad \text{for all}~~ j=0,\dots,t,
\end{align*}
which implies
\begin{align*}
    \Norm{\vx^j-\vx^*}^{\nu}\leq (a_j(n, \nu))^{\nu}\Norm{\vx^0-\vx^*}^{\nu} \leq \Norm{\vx^0-\vx^*}^{\nu} \leq \frac{\mu^2}{4L_f\fH_\nu n}, \qquad\text{for all}~~j=1,\dots,t,
\end{align*}
where the second inequality is based on Lemma \ref{le:s-mono-000} and the last inequality is based on the condition condition.


The update~(\ref{eq:update-1}) means the points $\{\vz_i^{t}\}_{i=1}^n$ can be written as $\{\vx^{t+1-n}, \cdots, \vx^{t}\}$, which implies
\begin{align*}
    \max\{\Norm{\vz_1^{t}-\vx^*}, \cdots, \Norm{\vz_n^{t}-\vx^*}\}=\max\{\Norm{\vx^{t+1-n}-\vx^*}, \cdots, \Norm{\vx^{t}-\vx^*}\}.
\end{align*}
Therefore, we have
\begin{align*}
    \Norm{\vz_i^{n} - \vx^*}^{\nu} \leq \frac{\mu^2}{4L_f\fH_\nu n} \qquad \text{for all}~~i=1,\dots,n.
\end{align*}

Combing with Lemma \ref{le:lb-Ht-new-1}, we have
\begin{align*}
    \sigma_{\min}(\mH^{t}) &\geq  \mu^2 - 2L_f\fH_\nu\sum_{i=1}^n \Norm{\vz_i^{t} - \vx^*}^\nu\\
    & \geq \mu^2 - 2L_f\fH_\nu n \frac{\mu^2}{4L_f\fH_\nu n}\\
    & = \mu^2 - \frac{\mu^2}{2} = \frac{\mu^2}{2}.
\end{align*}
Therefore, we achieve
\begin{align*}
    \mH^{t}  \succeq \frac{\mu^2}{2}\mI \qquad\text{and}\qquad
    \Norm{\mG^{t}} & = \Norm{(\mH^{t})^{-1}} \leq \frac{2}{\mu^2}.
\end{align*}
According to Lemma \ref{le:main-iter-1}, we have
\begin{align*}
    \Norm{\vx^{t+1} - \vx^*}
    & \leq \frac{L_f\fH_\nu }{1+\nu}\Norm{\mG^{t}}\sum_{i=1}^n\Norm{\vz_i^{t}-\vx^*}^{1+\nu}\\
    & \leq \frac{2L_f\fH_\nu }{(1+\nu)\mu^2}\sum_{i=1}^n\Norm{\vz_i^{t}-\vx^*}^{1+\nu}\\
    & \leq \frac{2L_f\fH_\nu }{(1+\nu)\mu^2}\left(\sum_{j=t-n+1}^{t} (a_j(n, \nu))^{1+\nu}\Norm{\vx^0 - \vx^*}^{1+\nu}\right)\\
    & \leq \frac{2L_f\fH_\nu }{(1+\nu)\mu^2}\left(\sum_{j=t-n+1}^{t} (a_j(n, \nu))^{1+\nu}\right)\Norm{\vx^0 - \vx^*}^{1+\nu}\\
    & \leq \frac{2L_f\fH_\nu }{(1+\nu)\mu^2}\frac{\mu^2}{4L_f\fH_\nu n}\left(\sum_{j=t-n+1}^{t+1}a_j(n, \nu)^{1+\nu}\right)\Norm{\vx^0 - \vx^*}\\
    & = \frac{1}{2(1+\nu)n}\left(\sum_{j=t-n+2}^{t+1}(a_j(n, \nu))^{1+\nu}\right)\Norm{\vx^0 - \vx^*}\\
    & = a_{t+1}(n, \nu)\Norm{\vx^0 - \vx^*}.
\end{align*}
Hence, we finish the induction.


Combining results of Part I, II and III completes the proof of (\ref{eq:Hxtxstar0}).

Since the non-singularity of $\mH^t$ and $\mH^{t+1}$ has been verified by result (\ref{eq:Hxtxstar0}), we can apply Lemma \ref{le:via-update} to achieve
\begin{align*}
    \sigma_{\min}(\mI + (\mV^t)^\top(\mH^t)^{-1}\mU^t) > 0.
\end{align*}
\end{proof}

\begin{thm}
\label{thm:holder-IGN-1-2}
We define the sequence $\{r_t\}_{t\geq 0}$ such that
\begin{align*}
    r_t\triangleq\begin{cases}
    \max\{\Norm{\vx^0 - \vx^*}, 1\},~~~~&t=0,\\[0.2cm]
    a_t(n, \nu)r_0,~~~~& t\geq 1,\\
\end{cases}
\end{align*}
where the sequence $\{a_t(n, \nu)\}_{t\geq 0}$ is defined by equation (\ref{eq:series}). 
Under the Assumptions \ref{asm:L-f}, \ref{asm:holder-g} and \ref{asm:b-J-sing}, running \IGN~(Algorithm \ref{alg:IGN-1}) with initial condition shown in Theorem \ref{thm:holder-IGN-1-1}, we have
    \begin{align}
    \label{eq:r_t_recursion}
    \Norm{\vx^t - \vx^*} \leq r_t
    \qquad\text{and}\qquad
    r_{t+1}\leq  c^{(1+\nu)^{\left(\floor{\frac{t}{n}}-1\right)}}r_t  
    \end{align}
    for all $t\geq n$, where
    \begin{align*}
    c = 1- \frac{1}{n}\left(1-\left(\frac{1}{2(1+\nu)}\right)^{1+\nu}\right).
    \end{align*}
\end{thm}

\begin{proof}
    The definition of $\{r_t\}_{t\geq 0}$ leads to 
    \begin{align*}
        r_0 = \max\{\Norm{\vx^0 - \vx^*}, 1\} \geq \Norm{\vx^0 - \vx^*}.
    \end{align*}
    According to Theorem \ref{thm:holder-IGN-1-1}, we have 
    \begin{align*}
    \Norm{\vx^t - \vx^*} \leq a_{t}(n, \nu)\Norm{\vx^0 - \vx^*} \leq a_t(n, \nu)r_0 = r_t.
    \end{align*}
    According to Lemma \ref{le:super-con}, we have
    \begin{align*}
         a_{t+1}(n, \nu)\leq  c^{(1+\nu)^{\left(\floor{\frac{t}{n}}-1\right)}}a_t(n, \nu) \qquad \text{for all}~~t \geq n.
    \end{align*}
    Thus, achieve
    \begin{align*}
        r_{t+1} = a_{t+1}(n, \nu)r_0\leq  c^{(1+\nu)^{\left(\floor{\frac{t}{n}}-1\right)}}a_t(n, \nu)r_0 =c^{(1+\nu)^{\left(\floor{\frac{t}{n}}-1\right)}}r_t  \qquad \text{for all}~~t \geq n,
    \end{align*}
    where
    \begin{align*}
        c = 1- \frac{1}{n}\left(1-\left(\frac{1}{2(1+\nu)}\right)^{1+\nu}\right).
    \end{align*}
\end{proof}

Combining the results of Theorem \ref{thm:holder-IGN-1-1} and  \ref{thm:holder-IGN-1-2}, we finish the proof of Theorem \ref{thm:holder-IGN-1}.

